// Ước lượng nhiễu phi tuyến f(q, qd) bằng ESO bậc 3
const { dhParams, inertiaList, qRad, qdRad, qDesiredRad, qdDesiredRad, qddDesiredRad, gains, gravityAcc } = ctx;
const n = qRad.length;

